import{_ as o,o as d,c as t,a2 as c}from"./chunks/framework.BU4O3IzQ.js";const g=JSON.parse('{"title":"Git命令","description":"","frontmatter":{"title":"Git命令","date":"2022-09-06T00:00:00.000Z","tags":["Git"],"section":"tech"},"headers":[],"relativePath":"tech/docs/Git命令.md","filePath":"tech/docs/Git命令.md","lastUpdated":1786092171000}'),a={name:"tech/docs/Git命令.md"};function i(s,e,r,l,p,n){return d(),t("div",null,[...e[0]||(e[0]=[c(`<h1 id="一-git-是什么" tabindex="-1">一：Git 是什么？ <a class="header-anchor" href="#一-git-是什么" aria-label="Permalink to &quot;一：Git 是什么？&quot;">​</a></h1><p class="article-meta"><time datetime="2022-09-06">2022-09-06</time><span class="article-tag">Git</span></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  Git是目前世界上最先进的分布式版本控制系统。</span></span></code></pre></div><h1 id="二-svn-与-git-的最主要的区别" tabindex="-1">二：SVN 与 Git 的最主要的区别? <a class="header-anchor" href="#二-svn-与-git-的最主要的区别" aria-label="Permalink to &quot;二：SVN 与 Git 的最主要的区别?&quot;">​</a></h1><p><code>SVN</code> 为集中式版本控制系统，版本库是集中存放在中央服务器的 单独搭建 <code>SVN</code> 服务器，不能离线工作 操作简单，代码保密性较强</p><p><code>GIT</code> 为分布式版本控制系统根本没有“中央服务器”，每个人的电脑上都是一个完整的版本库 适合分布式开发，强调个体 公共服务器压力和数据量都不会太大 速度快灵活 可以离线工作 操作复杂，代码保密性差</p><p><code>GitHub</code>,免费的远程仓库，如果是个人的开源项目，放到 <code>GitHub</code> 上是完全没有问题的。<code>GitHub</code> 还是一个开源协作社区，通过 <code>GitHub</code>，既可以让别人参与你的开源项目，也可以参与别人的开源项目。</p><p><code>SVN</code> 的存储需要依赖一个服务器，而 <code>git</code> 所有的东西是放在线上的。节约成本，省时省力。</p><p><code>&#39;Please tell me who you are.&#39;</code></p><p>查看全局配置   <code>git config --global --list</code></p><p>命令   <code>git config --global user.name &quot;你的 git 名称&quot;</code> 命令   <code>git config --global user.email &quot;你的 git 验证邮箱&quot;</code></p><p><code>git</code> 命令行中的操作命令： 命令  <code>cd D:</code>   进入 相应的磁盘 命令  <code>mkdir</code>   创建目录 命令  <code>cd</code> 进入当前盘符中的文件夹 命令  <code>pwd</code> 显示当前工作目录的全路径 命令  <code>rm</code>   删除文件 命令  <code>ls</code> 查看文件夹下的子文件</p><p>然后！最重要的步骤来了！！<code>git init</code></p><p>命令  <code>git init</code> 显示成功后去相应的文件夹中查看是不是多了一个<code>.git</code> 文件</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这个文件夹就是你的版本库了，把项目放在文件夹下。</span></span></code></pre></div><hr><h1 id="三-将文件提交到-git-服务器。" tabindex="-1">三.将文件提交到 git 服务器。 <a class="header-anchor" href="#三-将文件提交到-git-服务器。" aria-label="Permalink to &quot;三.将文件提交到 git 服务器。&quot;">​</a></h1><p>你的本地仓库由 <code>git</code> 维护的三棵“树”组成： 　　第一个是你的 工作目录，它持有实际文件； 　　第二个是 暂存区<code>（Index）</code>，临时保存你的改动； 　　最后是 <code>HEAD</code>，指向你最近一次提交后的结果。</p><h2 id="_1-打开-git-bash" tabindex="-1">1.打开 Git Bash <a class="header-anchor" href="#_1-打开-git-bash" aria-label="Permalink to &quot;1.打开 Git Bash&quot;">​</a></h2><p>命令 <code>git add ‘文件名’</code><code>git add -u</code>   提交所有被修改<code>(modified)</code>和被删除<code>(deleted)</code>文件，不包括新文件<code>(new)</code><code>git add . </code>  提交所有新文件<code>(new)</code>和被修改<code>(modified)</code>文件，不包括被删除<code>(deleted)</code>文件 <code>git add -A</code>   提交所有变化</p><p>把咱们的文件存放在一个神秘的地方 <code>&gt;&gt;&gt;&gt; 暂存区</code> （暂存区在本机）</p><h2 id="_2-把文件提交到本地仓库中去。" tabindex="-1">2.把文件提交到本地仓库中去。 <a class="header-anchor" href="#_2-把文件提交到本地仓库中去。" aria-label="Permalink to &quot;2.把文件提交到本地仓库中去。&quot;">​</a></h2><p><code>git commit -m &#39;我提交时候的备注（注释）&#39;</code></p><h2 id="_3-查看-commit-状态" tabindex="-1">3.查看 commit 状态 <a class="header-anchor" href="#_3-查看-commit-状态" aria-label="Permalink to &quot;3.查看 commit 状态&quot;">​</a></h2><p><code>git status</code>   用于显示工作目录和暂存区的状态。</p><h2 id="_4-查看修改内容。" tabindex="-1">4.查看修改内容。 <a class="header-anchor" href="#_4-查看修改内容。" aria-label="Permalink to &quot;4.查看修改内容。&quot;">​</a></h2><p><code>git diff</code> 你的文件名   会出现更改信息； 将更改后的东西提交上去，和之前一样。先 <code>add</code> 然后再 <code>commit</code> 。</p><h2 id="_5-版本退回" tabindex="-1">5.版本退回 <a class="header-anchor" href="#_5-版本退回" aria-label="Permalink to &quot;5.版本退回&quot;">​</a></h2><p><code>git log</code>          （ 查看日志） <code>git reflog</code></p><p><code>git reset --hard HEAD^</code>   退回到上个版本 如果需要退回好多版本就在后面加上 ^ 例： <code>git reset --hard HEAD^^</code>退回两个版本。 <code>git reset --hard 191e0c7</code>   回退到指定版本</p><h2 id="_6-删除" tabindex="-1">6.删除 <a class="header-anchor" href="#_6-删除" aria-label="Permalink to &quot;6.删除&quot;">​</a></h2><p>新建一个 <code>b.txt</code>，然后<code>commit</code> 到库中。 并删除。</p><p>命令 1. <code>git add</code></p><p>命令 2. <code>git commit -m ‘备注’</code></p><p>命令 3. <code>rm b.txt</code>   这个是删除<code>b</code>文件的命令</p><p>回过头来看文件夹中的 <code>b.txt</code></p><p><code>b.txt</code> 不见了，查看下状态。 可以 <code>commit</code>，可以放弃修改<code>git reset --hard</code> 版本号来回复文件。</p><h2 id="_7-连接远程仓库" tabindex="-1">7.连接远程仓库 <a class="header-anchor" href="#_7-连接远程仓库" aria-label="Permalink to &quot;7.连接远程仓库&quot;">​</a></h2><ol><li><code>git init</code>   -&gt; 创建版本库</li><li><code>git add 文件名</code>   -&gt; 添加到暂存区</li><li><code>git commit -m &#39;提交注释&#39;</code>   -&gt;提交到本地仓库</li></ol><p>然后连接本地仓库，并将自己的库 push 到服务器中去。</p><ol><li>命令 1. <code>git remote add origin https: // github.com/</code>你的账号/你的项目名称   设置远程仓库地址</li><li>命令 2. <code>git push -u origin master</code> 将本地的库推送到 <code>master</code> 分支 （就是推送到服务器上）</li></ol><p><code>git push -u -f origin master</code>(提交到远程仓库，这个命令中的 <code>-f</code> 是强制推送，因为远程仓库只有初始化的文件，所以强制推送上去就行了，不加<code>-f</code> 会报当前分支没有远程分支，强制推送可以覆盖 <code>master</code>，这样就完成了第一次提交的步骤)</p><p><code>git remote -v</code>   查看远程仓库地址 <code>git remote rm origin</code>   删除远程仓库地址</p><p>在服务器上查看是否推送成功。</p><p>从现在开始，只需要 <code>git push</code> 就可以把本机的代码提交到远程仓库。 <code>git push</code>     (提交 <code>master</code> 分支 到远程仓库) <code>git push origin</code> 分支名     (提交其他分支 到远程仓库)</p><p>获取远程仓库的更新数据： <code>git fetch</code>：相当于是从远程获取最新到本地，不会自动 <code>merge</code><code>git pull</code>：相当于是从远程获取最新版本并 merge 到本地 <code>git pull origin 分支名</code>   更新某个远程分支到本地</p><p>从服务器克隆数据， <code>git clone</code><code>git clone</code> <a href="https://github.com/yanghuaizhi1210/GitTest" target="_blank" rel="noreferrer">https://github.com/yanghuaizhi1210/GitTest</a> 将服务器端的数据克隆过来。</p><p>如果输入<code>$ git remote add origin</code> <a href="mailto:git@github.com" target="_blank" rel="noreferrer">git@github.com</a>:djqiang（github 帐号名）/gitdemo（项目名）.git 提示出错信息：fatal: remote origin already exists. 解决办法如下： 1、先输入<code>$ git remote rm origin</code> 2、再输入<code>$ git remote add origin</code> <a href="mailto:git@github.com" target="_blank" rel="noreferrer">git@github.com</a>:djqiang/gitdemo.git 就不会报错了！ 3、如果输入<code>$ git remote rm origin</code> 还是报错的话，error: Could not remove config section &#39;remote.origin&#39;. 我们需要修改 gitconfig 文件的内容 4、找到你的 <code>github</code> 的安装路径，我的是 <code>C:\\Users\\ASUS\\AppData\\Local\\GitHub\\PortableGit_ca477551eeb4aea0e4ae9fcd3358bd96720bb5c8\\etc</code> 5、找到一个名为 <code>gitconfig</code> 的文件，打开它把里面的<code>[remote &quot;origin&quot;]</code>那一行删掉就好了！</p><p>生成秘钥： （1）首先检查电脑是否曾经生成过秘钥 <code>cd ~/.ssh</code> 若打开该文件夹为空，则表示没有生成过秘钥，进入第二步。（~表示根目录） (2) 生成秘钥 <code>ssh-keygen -t rsa -C &quot;your email&quot;</code> 命令要求输入密码，不用输，三个回车即可。 执行成功后，会在主目录<code>.ssh</code> 路径下生成两个文件：<code>id_rsa</code> 私钥文件；<code>id_rsa.pub</code> 公钥文件；</p><p>登陆 <code>github</code> 帐户点击头像，然后 <code>Settings -&gt; 左栏点击 SSH and GPG keys -&gt; 点击 New SSH key</code> 在远程仓库 <code>gitlab</code> 上添加 <code>title</code> 和 <code>key</code>，和本地的一致。<code>title</code> 可以自己取一个容易区分的名字，<code>key</code> 为 <code>id_rsa.pub</code> 中的内容（全部复制，可用 <code>cat id_rsa.pub</code> 命令打开）</p><p>配置了 <code>ssh</code> 秘钥，使用远程仓库的 <code>ssh</code> 地址提交 <a href="https://www.cnblogs.com/superGG1990/p/6844952.html" target="_blank" rel="noreferrer">https://www.cnblogs.com/superGG1990/p/6844952.html</a></p><hr><h1 id="分支操作" tabindex="-1">分支操作 <a class="header-anchor" href="#分支操作" aria-label="Permalink to &quot;分支操作&quot;">​</a></h1><p>查看分支：<code>git branch</code> 当前分支前有 <code>*</code> 号</p><p>创建分支：<code>git branch</code></p><p>切换分支：<code>git checkout</code></p><p>创建+切换分支：<code>git checkout -b</code></p><p>合并某分支到当前分支：<code>git merge</code></p><p>删除分支：<code>git branch -d</code></p><p><strong>合并分支：</strong></p><p>1、先建一个分支              <code>git branch</code> 分支名</p><p>2、切换到新建的分支          <code>git checkout</code> 分支名</p><p>3、提交分支上的代码          <code>git add .</code>    <code>git commit -m “提交注释”</code></p><p>4、切换至主分支上            <code>git checkout master</code></p><p>5、然后合并分支              <code>git merge 分支</code> 6、合并完以后就 <code>push</code>          最好先 <code>pull</code> 一次   然后 <code>git push</code></p><p>7、切换到自己的分支          <code>git merge</code> 线上分支名称</p><p>设置 <code>git</code> 忽略文件： 1.创建文件：<code>.gitignore</code> 2.忽略文件列表</p><h1 id="gitignore-忽略文件列表" tabindex="-1">.gitignore 忽略文件列表 <a class="header-anchor" href="#gitignore-忽略文件列表" aria-label="Permalink to &quot;.gitignore 忽略文件列表&quot;">​</a></h1><p><code>.DS_Store</code><code>node_modules/</code><code>/dist/</code><code>npm-debug.log*</code><code>yarn-debug.log*</code><code>yarn-error.log*</code></p><h1 id="editor-directories-and-files" tabindex="-1">Editor directories and files <a class="header-anchor" href="#editor-directories-and-files" aria-label="Permalink to &quot;Editor directories and files&quot;">​</a></h1><p><code>.idea</code><code>.vscode</code><code>_.suo</code><code>*.ntvs*</code><code>_.njsproj</code><code>*.sln</code></p><p>如果出现如： <strong>Please enter a commit message to explain why this merge is necessary,# especially if it merges an updated upstream into a topic branch.</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>“:wq”是Linux操作系统命令： 表示强制性写入文件并退出。</span></span>
<span class="line"><span>输入“:wq”，注意是英文输入状态下的冒号，然后按下“Enter”键。</span></span></code></pre></div><hr><h1 id="git-submodule" tabindex="-1">Git Submodule <a class="header-anchor" href="#git-submodule" aria-label="Permalink to &quot;Git Submodule&quot;">​</a></h1><p>有的时候我们会遇到仓库嵌套的问题，即一个仓库内部还有一个 <code>git</code> 仓库。这时就需要使用到 <code>git submodule</code> 模块化。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git submodule add 远程仓库地址  仓库名/</span></span></code></pre></div><p>执行此命令后会在外层仓库根目录下生成<strong>一个.gitmodules 文件</strong> 如果想删除模块的话，可以执行</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git rm -r --cached 远程仓库名/，并删除对应的.gitmodules文件中的模块信息</span></span></code></pre></div><h1 id="git-push-时遇到-rejected-master-master-non-fast-forward-的问题" tabindex="-1">git push 时遇到：！[rejected] master -&gt; master(non-fast-forward)的问题 <a class="header-anchor" href="#git-push-时遇到-rejected-master-master-non-fast-forward-的问题" aria-label="Permalink to &quot;git push 时遇到：！[rejected] master -&gt; master(non-fast-forward)的问题&quot;">​</a></h1><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. git pull origin master --allow-unrelated histories 把远程和本地同步，消除差异</span></span>
<span class="line"><span>2. git add</span></span>
<span class="line"><span>3. git commit -m</span></span>
<span class="line"><span>4. git push origin master</span></span></code></pre></div><h1 id="git-stash" tabindex="-1">git stash <a class="header-anchor" href="#git-stash" aria-label="Permalink to &quot;git stash&quot;">​</a></h1><h2 id="应用场景" tabindex="-1">应用场景 <a class="header-anchor" href="#应用场景" aria-label="Permalink to &quot;应用场景&quot;">​</a></h2><blockquote><ol><li>当正在 <code>dev</code> 分支上开发某个项目，这时项目中出现一个 <code>bug</code>，需要紧急修复，但是正在开发的内容只是完成一半，还不想提交，这时可以用<code>git stash</code>命令将修改的内容保存至堆栈区，然后顺利切换到 <code>fix</code> 分支进行 <code>bug</code> 修复，修复完成后，再次切回到 <code>dev</code> 分支，从堆栈中恢复刚刚保存的内容。</li><li>由于疏忽，本应该在 dev 分支开发的内容，却在 <code>master</code> 上进行了开发，需要重新切回到 <code>dev</code> 分支上进行开发，可以用<code>git stash</code>将内容保存至堆栈中，切回到 <code>dev</code> 分支后，再次恢复内容即可。 总的来说，<code>git stash</code>命令的作用就是将目前还不想提交的但是已经修改的内容进行保存至堆栈中，后续可以在某个分支上恢复出堆栈中的内容。这也就是说，<code>stash</code> 中的内容不仅仅可以恢复到原先开发的分支，也可以恢复到其他任意指定的分支上。<code>git stash</code>作用的范围包括工作区和暂存区中的内容，也就是说没有提交的内容都会保存至堆栈中。</li></ol></blockquote><h2 id="常用的用法" tabindex="-1">常用的用法 <a class="header-anchor" href="#常用的用法" aria-label="Permalink to &quot;常用的用法&quot;">​</a></h2><ol><li><code>git stash save &quot;save message&quot;</code> : 执行存储时，添加备注，方便查找，只有 git stash 也要可以的，但查找时不方便识别。</li><li><code>git stash list</code> ：查看 <code>stash</code> 了哪些存储</li><li><code>git stash show</code> ：显示做了哪些改动，默认 <code>show</code> 第一个存储,如果要显示其他存贮，后面加 <code>stash@{$num}</code>，比如第二个 <code>git stash show stash@{1}</code></li><li><code>git stash show -p</code> : 显示第一个存储的改动，如果想显示其他存存储，命令：<code>git stash show stash@{$num} -p</code> ，比如第二个：<code>git stash show stash@{1} -p</code></li><li><code>git stash apply</code> :应用某个存储,但不会把存储从存储列表中删除，默认使用第一个存储,即 <code>stash@{0}</code>，如果要使用其他个，<code>git stash apply stash@{$num}</code> ， 比如第二个：<code>git stash apply stash@{1}</code></li><li><code>git stash pop</code> ：命令恢复之前缓存的工作目录，将缓存堆栈中的对应 <code>stash</code> 删除，并将对应修改应用到当前的工作目录下,默认为第一个 <code>stash</code>,即 <code>stash@{0}</code>，如果要应用并删除其他 <code>stash</code>，命令：<code>git stash pop stash@{$num}</code> ，比如应用并删除第二个：<code>git stash pop stash@{1}</code></li><li><code>git stash drop stash@{$num}</code> ：丢弃<code>stash@{$num}</code>存储，从列表中删除这个存储</li><li><code>git stash clear</code> ：删除所有缓存的 <code>stash</code></li></ol><hr><h1 id="svn-使用" tabindex="-1">SVN 使用 <a class="header-anchor" href="#svn-使用" aria-label="Permalink to &quot;SVN 使用&quot;">​</a></h1><p>使用 <code>VisualSVN Server</code> 建立版本库 <a href="https://www.cnblogs.com/lcyuhe/p/4539696.html" target="_blank" rel="noreferrer">https://www.cnblogs.com/lcyuhe/p/4539696.html</a></p>`,89)])])}const u=o(a,[["render",i]]);export{g as __pageData,u as default};
